import{_ as n,C as l,o as t,c as h,a6 as a,b as r,w as o,a as s,E as i,af as c}from"./chunks/framework.DIp0zHSV.js";const b=JSON.parse('{"title":"Layout View and Layout Card","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/layout-view.md","filePath":"architecture/layout-view.md","lastUpdated":1794278866000}'),g={name:"architecture/layout-view.md"};function p(u,e,m,v,y,w){const d=l("Mermaid");return t(),h("div",null,[e[2]||(e[2]=a('<h1 id="layout-view-and-layout-card" tabindex="-1">Layout View and Layout Card <a class="header-anchor" href="#layout-view-and-layout-card" aria-label="Permalink to &quot;Layout View and Layout Card&quot;">​</a></h1><p>LCARdS has one CSS Grid layout engine with three front ends:</p><ul><li><strong>The layout view</strong> (<code>custom:lcards-layout-view</code>, <code>src/views/lcards-layout-view.js</code>): a Lovelace view type (a <code>LovelaceViewElement</code>) that renders the grid for a whole view and has an in-view WYSIWYG editor in dashboard edit mode.</li><li><strong>The layout card</strong> (<code>custom:lcards-layout-card</code>, <code>src/cards/lcards-layout-card.js</code>): the same grid as a card, to nest a sub-grid in one area of a view (or in any view or stack). It is read-only on the dashboard.</li><li><strong>The Layout Studio</strong> (<code>src/editor/dialogs/lcards-layout-studio-dialog.js</code>): the full-screen dialog the layout card&#39;s GUI editor opens, with a live preview and the same grid editor on a large canvas.</li></ul><p>This page covers how they are built and the non-obvious constraints behind the design. The user docs are <a href="./../cards/layout-view/">Layout View</a> and <a href="./../cards/layout-card/">Layout Card</a>; the <a href="./shell-strategy.html">Shell Strategy</a> generates a whole dashboard on top of both.</p><p>The view and the shared pieces live in <code>src/views/</code>:</p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>lcards-layout-view.js</code></td><td>The view element: renders the grid, mounts Home Assistant cards, owns config and persistence, manages the editor overlay.</td></tr><tr><td><code>lcards-grid-edit-overlay.js</code></td><td>The editor chrome (Layout mode): track handles, headers, area overlays, toolbars, settings panels. A lazy chunk: the view imports it on first edit, the studio imports it with itself.</td></tr><tr><td><code>layout-edit-chrome.js</code></td><td>Shared edit-mode chrome for the view and the overlay: mdi icon paths, the toolbar strip and panel styles, the Layout / Cards toggle, the dock width and breakpoint.</td></tr><tr><td><code>layout-grid-utils.js</code></td><td>Pure, DOM-free functions: track-list parsing and serialising, 2D area manipulation, area-settings reconciliation.</td></tr><tr><td><code>layout-render.js</code></td><td>Shared render helpers (<code>buildGridStyle</code>, <code>applyCardPlacement</code>, <code>applyGridItemHeight</code>, <code>renderAreaSurfaces</code>, <code>measureGridFrame</code>, <code>resolveColorValue</code>) used by the view, the card and the studio.</td></tr><tr><td><code>layout-edit-dialogs.js</code></td><td>Shared <code>ha-dialog</code> helpers: confirm (destructive actions), info and prompt.</td></tr></tbody></table><p>The card side:</p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>cards/lcards-layout-card.js</code></td><td>Container card (a plain <code>LitElement</code>, not an <code>LCARdSCard</code>): renders the same grid, builds its own children as <code>hui-card</code> wrappers (so native Visibility works) and passes <code>hass</code> down. Read-only on the dashboard.</td></tr><tr><td><code>cards/schemas/layout-card-schema.js</code></td><td>The card&#39;s JSON Schema (registered by <code>LCARdSLayoutCard.registerSchema()</code>; also the studio&#39;s YAML tab schema).</td></tr><tr><td><code>editor/cards/lcards-layout-card-editor.js</code></td><td>The card&#39;s GUI editor: a thin launcher that shows a summary and opens the Layout Studio, then relays the studio&#39;s <code>config-changed</code> to Home Assistant.</td></tr><tr><td><code>editor/dialogs/lcards-layout-studio-dialog.js</code></td><td>The full-screen studio: one live preview card plus one grid overlay on a large canvas, a Layout tab (global and per-area settings), a tab per card (inline <code>hui-card-element-editor</code> plus placement) and a YAML tab.</td></tr></tbody></table><hr><h2 id="component-model" tabindex="-1">Component model <a class="header-anchor" href="#component-model" aria-label="Permalink to &quot;Component model&quot;">​</a></h2>',10)),(t(),r(c,null,{default:o(()=>[i(d,{id:"mermaid-144",class:"mermaid",graph:"graph%20TB%0A%20%20%20%20subgraph%20View%5B%22lcards-layout-view%20(LovelaceViewElement)%22%5D%0A%20%20%20%20%20%20%20%20Grid%5B%22%23grid-root%5Cnreal%20CSS%20grid%20%2B%20mounted%20cards%22%5D%0A%20%20%20%20%20%20%20%20Surfaces%5B%22area%20surfaces%5Cn(layout.areas%20backings)%22%5D%0A%20%20%20%20%20%20%20%20Save%5B%22_saveViewConfig%5Cnserialized%20lovelace%20save%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Overlay%5B%22lcards-grid-edit-overlay%20(Layout%20mode)%22%5D%0A%20%20%20%20%20%20%20%20Ghost%5B%22%23ghost-grid%5Cn(measurement%20source)%22%5D%0A%20%20%20%20%20%20%20%20Chrome%5B%22headers%20%C2%B7%20handles%20%C2%B7%20area%20overlays%20%C2%B7%20panels%22%5D%0A%20%20%20%20end%0A%20%20%20%20HA%5B%22Home%20Assistant%3A%20lovelace%2C%20hass%2C%20pre-built%20hui-card%20elements%22%5D%0A%0A%20%20%20%20HA%20--%3E%7C%22set%20lovelace%20%2F%20hass%20%2F%20cards%22%7C%20View%0A%20%20%20%20View%20--%3E%7C%22import()%20on%20first%20edit%2C%20then%20createElement%20%2B%20properties%22%7C%20Overlay%0A%20%20%20%20Overlay%20--%3E%7C%22grid-state-changed%2C%20grid-preview-changed%2C%3Cbr%2F%3Earea-settings-changed%2C%20area-renamed%2C%20area-cards-changed%2C%3Cbr%2F%3Eadd-card-to-area%2C%20layout-settings-changed%2C%3Cbr%2F%3Eswitch-to-cards-mode%2C%20dock-changed%22%7C%20View%0A%20%20%20%20View%20--%3E%20Save%20--%3E%7C%22lovelace.saveConfig%22%7C%20HA%0A%0A%20%20%20%20style%20View%20fill%3A%231c3c55%2Cstroke%3A%2337a6d1%2Ccolor%3A%23eee%0A%20%20%20%20style%20Overlay%20fill%3A%232f3749%2Cstroke%3A%2352596e%2Ccolor%3A%23eee%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a('<p>The view holds the parsed grid state (<code>_columns</code>, <code>_rows</code>, <code>_areas</code>, <code>_gap</code>) and the raw <code>_config</code>. The overlay is <strong>stateless about persistence</strong>: it edits a copy of the grid passed in as properties and emits events; the view is the single writer.</p><hr><h2 id="imperative-overlay-creation-scoped-registry-constraint" tabindex="-1">Imperative overlay creation (scoped-registry constraint) <a class="header-anchor" href="#imperative-overlay-creation-scoped-registry-constraint" aria-label="Permalink to &quot;Imperative overlay creation (scoped-registry constraint)&quot;">​</a></h2><p>The view does <strong>not</strong> put <code>&lt;lcards-grid-edit-overlay&gt;</code> in its Lit template. Home Assistant builds custom view elements through a <em>scoped</em> custom-element registry (<code>create-view-element.ts</code>). A globally-registered element nested via a Lit template tag inside that view throws:</p><blockquote><p><code>Failed to construct &#39;HTMLElement&#39;: This instance is already constructed</code></p></blockquote><p>So <code>_syncEditOverlay()</code> (called from <code>updated()</code>) starts <code>import(&#39;./lcards-grid-edit-overlay.js&#39;)</code> (the overlay and the editor components it uses are a lazy chunk, which keeps them out of the main chunk&#39;s size budget), creates the overlay with <code>document.createElement(&#39;lcards-grid-edit-overlay&#39;)</code> (the <strong>global</strong> registry; the element upgrades when its definition arrives and keeps the properties set before then), wires events with <code>addEventListener</code>, sets state via properties, and appends it to <code>renderRoot</code>. It is removed when leaving Layout mode and on disconnect.</p><p>The <strong>layout card</strong> uses the same imperative pattern, but inside the <strong>Layout Studio</strong> dialog rather than Home Assistant&#39;s cramped card-edit dialog: the studio creates a single preview card <em>and</em> a single grid overlay via <code>document.createElement</code> on a large canvas. Because the studio owns one of each for its lifetime (and is destroyed on close), the duplicate-overlay/alignment problems of in-dialog editing don&#39;t arise. Editing needs <strong>no edit-mode detection</strong> and no nested-path <code>saveConfig</code>; overlay events update the studio&#39;s working config, and <strong>Save</strong> fires one <code>config-changed</code>, which the card&#39;s GUI editor relays to Home Assistant (see <a href="#the-layout-studio">The Layout Studio</a>).</p><hr><h2 id="the-ghost-grid-measurement-pattern" tabindex="-1">The ghost-grid measurement pattern <a class="header-anchor" href="#the-ghost-grid-measurement-pattern" aria-label="Permalink to &quot;The ghost-grid measurement pattern&quot;">​</a></h2><p>The editor chrome is <strong>not</strong> laid out with CSS grid. Instead the overlay renders a transparent <code>#ghost-grid</code> with the same <code>grid-template-*</code>, and after each render <code>_measure()</code> (in a <code>requestAnimationFrame</code>) calls <code>getBoundingClientRect()</code> on every ghost cell to build <code>_cells[r][c]</code> pixel rects. All chrome (column/row headers, resize handles, area overlays, cell targets, popovers) is then <strong>positioned absolutely</strong> from those measurements via <code>_positionElements()</code>.</p><p>This avoids the offset bug that occurs when header/ruler tracks consume grid space. A <code>ResizeObserver</code> on the overlay re-measures whenever the view resizes (e.g. the Home Assistant sidebar expands/collapses), keeping the chrome aligned with the real grid.</p><h3 id="header-gutter" tabindex="-1">Header gutter <a class="header-anchor" href="#header-gutter" aria-label="Permalink to &quot;Header gutter&quot;">​</a></h3><p>In edit mode the grid reserves room for the editor chrome so it never covers cards: <code>buildGridStyle(..., { editMode })</code> pads <code>#grid-root</code> by <code>editReserve(mode)</code> (<code>layout-grid-utils.js</code>): <code>EDIT_BAR_HEIGHT</code> (48px) on top for the toolbar strip in both modes, plus <code>GRID_EDIT_GUTTER</code> (28px) on top and left in Layout mode for the column/row headers. The view passes its edit sub-mode; the layout card passes <code>&#39;grid&#39;</code> while the Layout Studio sets <code>editing</code>. <code>_applyVisibilityRowHeights()</code> subtracts the grid&#39;s padding before sizing <code>fr</code> rows.</p><p>The overlay&#39;s ghost grid starts where the real grid&#39;s first cell starts: the parent calls <code>measureGridFrame(grid, overlay)</code> (<code>layout-render.js</code>), which returns the resolved px tracks (<code>measureColumns</code> / <code>measureRows</code>) and the first cell&#39;s offset (<code>measureOffset</code>, covering the reserve, <code>padding</code>, <code>margin</code> and border). Headers are positioned in the gutter (<code>cell.top - GUTTER</code>), so they cannot overlap area controls.</p><h3 id="stacking-order-and-hit-targets" tabindex="-1">Stacking order and hit targets <a class="header-anchor" href="#stacking-order-and-hit-targets" aria-label="Permalink to &quot;Stacking order and hit targets&quot;">​</a></h3><p>The overlay keeps one z-index scale (<code>Z</code> at the top of the file): cell targets &lt; area tiles &lt; resize segments &lt; headers &lt; gutter resize segment &lt; area grips &lt; selection / area preview &lt; toolbar &lt; dock and popups &lt; drag chip. Resize handles are split into one segment per cell along a boundary plus one in the gutter (inserting a track is in the track menu, so nothing covers the handle); a segment whose two cells belong to the same area is hidden, so the middle of a spanning area stays the area. Menus (<code>ha-dropdown</code>) render in the top layer, so the host&#39;s <code>overflow: hidden</code> never clips them; <code>ha-dropdown</code> is <code>display: contents</code>, so the trigger <code>ha-icon-button</code> is what gets positioned.</p><h3 id="docked-inspector" tabindex="-1">Docked inspector <a class="header-anchor" href="#docked-inspector" aria-label="Permalink to &quot;Docked inspector&quot;">​</a></h3><p>Grid settings, a track&#39;s settings and an area&#39;s settings share one <code>.edit-dock</code> (<code>editDockStyles</code> in <code>layout-edit-chrome.js</code>): <code>_openDock({ settings | track | area })</code> shows one subject and replaces any other; while it shows an area it follows <code>_selectArea()</code>. The overlay fires <code>dock-changed</code> (<code>{ open }</code>) when it opens or closes. The view sets its <code>dock-open</code> attribute (<code>:host([dock-open])</code> pads the host by <code>EDIT_DOCK_WIDTH</code>, so <code>#grid-root</code> narrows) and the layout studio toggles <code>.dock-open</code> on its canvas; below <code>DOCK_SHEET_BREAKPOINT</code> the dock is a bottom sheet over the grid instead. In card mode the view shows a card&#39;s placement in its own dock (<code>_renderPlacementPanel</code>). The overlay&#39;s ResizeObserver re-measures when the grid narrows.</p><h3 id="area-move-and-resize" tabindex="-1">Area move and resize <a class="header-anchor" href="#area-move-and-resize" aria-label="Permalink to &quot;Area move and resize&quot;">​</a></h3><p>The selected area gets four edge grips (<code>_renderAreaGrips</code>), and its name chip is a move handle. <code>_areaDragStart/Move/End</code> hit-test cells with <code>_cellAtPoint</code>, build the target bounds (edges clamp to at least one cell; a move clamps to the grid) and validate them with <code>setAreaBounds()</code> (<code>layout-grid-utils.js</code>: frees the area&#39;s own cells, refuses overlaps with other areas). <code>.area-preview</code> shows the target, <code>.blocked</code> in the error colour. Only a drag that ends on a valid target commits (<code>grid-state-changed</code>); cards and <code>layout.areas</code> refer to the area by name, so they follow it unchanged.</p><h3 id="stacked-cards-card-mode" tabindex="-1">Stacked cards (card mode) <a class="header-anchor" href="#stacked-cards-card-mode" aria-label="Permalink to &quot;Stacked cards (card mode)&quot;">​</a></h3><p>When several cards share a <code>grid-area</code>, <code>_placeCards()</code> adds a <code>.stack-picker</code> (one pill per card) to that area. The picked card (<code>_stackFocus[area]</code>, default the top one) gets a z-index above the stack&#39;s own and the others <code>pointer-events: none</code>, so its edit controls can be reached.</p><h3 id="unified-pointer-dispatch" tabindex="-1">Unified pointer dispatch <a class="header-anchor" href="#unified-pointer-dispatch" aria-label="Permalink to &quot;Unified pointer dispatch&quot;">​</a></h3><p><code>connectedCallback</code> binds <code>pointermove</code> / <code>pointerup</code> / <code>pointercancel</code> to the overlay element (not <code>document</code>, because of shadow-DOM boundaries). Every drag captures its pointer (<code>setPointerCapture</code>), so a release outside the view still arrives and ends the drag; <code>pointercancel</code> ends any drag (a resize keeps the size reached). <code>_onAnyPointerMove</code>/<code>_onAnyPointerUp</code>/<code>_onAnyPointerCancel</code> route to whichever drag is active: track resize, header reorder, rubber-band area selection, or an area move / resize. The rubber-band hit-tests the measured cell rects (<code>_cellAtPoint</code>), so capturing on the first cell is safe; a click without a drag on an empty cell creates a one-cell area (handled in <code>_selUp</code>, since the captured pointer sends the click to the cell).</p><hr><h2 id="card-placement-per-area-surfaces" tabindex="-1">Card placement &amp; per-area surfaces <a class="header-anchor" href="#card-placement-per-area-surfaces" aria-label="Permalink to &quot;Card placement &amp; per-area surfaces&quot;">​</a></h2><p><code>_placeCards()</code> rebuilds <code>#grid-root</code> whenever cards or layout change:</p><ol><li><strong>Area surfaces</strong> (<code>renderAreaSurfaces()</code>, from <code>layout-render.js</code>): for each entry in <code>layout.areas</code>, a non-interactive <code>.area-surface</code> div is appended first (so cards paint above it by DOM order), styled by <code>applyAreaSurfaceStyle()</code>. <code>theme:</code> tokens in colors are resolved via <code>window.lcards.core.themeManager.resolver</code>.</li><li><strong>Cards</strong>: each Home Assistant card element gets placement applied by <code>applyCardPlacement(gridItem, cardEl, viewLayout, cardMargin, cardOverflow, areaSettings, { cellFits })</code> (also from <code>layout-render.js</code>). <code>cellFits</code> comes from <code>cellHeightDefinite()</code> (<code>layout-grid-utils.js</code>): when the card&#39;s area has a definite height, the grid item gets <code>data-lcards-cell-fits</code> and an LCARdS button in it follows the cell instead of its preset&#39;s minimum height. <code>applyGridItemHeight()</code> forwards a card&#39;s own <code>height</code> to the grid item.</li></ol><p><strong>Precedence:</strong> global (<code>card_margin</code> / <code>card_overflow</code>) → per-area (<code>layout.areas[name]</code>) → per-card (<code>view_layout</code>). Grid placement and alignment land on the <em>grid item</em> (the card, or its edit-mode wrapper); <code>overflow</code> lands on the card so content clips regardless of the wrapper.</p><p>In edit mode every card element is <code>inert</code> (as Home Assistant does in its own views), so a click never runs a card&#39;s tap action. In Card mode each card is wrapped in a <code>.card-edit-wrap</code> (the grid item, <code>isolation: isolate</code>) with Home Assistant&#39;s <code>hui-card-edit-mode</code> controls rendered by <code>_renderCardControls()</code>: the whole card is the edit target (scrim + pencil, <code>ll-edit-card</code>), and a ⋮ <code>ha-dropdown</code> offers Edit, Placement &amp; spacing and Delete (<code>ll-delete-card</code>, so Home Assistant shows its <em>Undo</em> toast). Controls show on hover, focus, or a first tap on touch screens (<code>_onDocPointerDown</code>). Empty areas get an <strong>Add card</strong> placeholder.</p><p>Every edit is a <code>lovelace.saveConfig</code>, and Home Assistant&#39;s <code>hui-root</code> commits each config change to its undo stack, so the dashboard toolbar&#39;s Undo / Redo covers the view&#39;s edits. Multi-key changes (alignment, overflow, per-area settings) are sent as one patch, so each is one save and one undo step.</p><p>Saves are serialized by <code>_saveViewConfig()</code>, which also waits for the previous config change&#39;s <code>lovelace_updated</code> event before saving (<code>_waitForSaveEvent()</code>, 2s fallback) and merges saves requested in the same tick. Home Assistant&#39;s panel ignores only <strong>one</strong> update event per <code>saveConfig</code> (a boolean flag); two saves before the first event arrives make the second event look external, and Home Assistant shows &quot;Dashboard updated in another session&quot;. The classic trigger is saving from the <code>lovelace</code> setter right after Home Assistant saved a card (adding <code>grid-area</code> to a new card, restoring a stripped <code>view_layout</code>).</p><p>Cards are <strong>always placed</strong>; per-card visibility is not the view&#39;s concern. Home Assistant hands the view <code>hui-card</code> wrappers, which evaluate each card&#39;s native <strong>Visibility</strong> conditions and hide themselves reactively. The view therefore implements no <code>view_layout.show</code> handling (unlike upstream layout-card, whose card mode bypasses the <code>hui-card</code> wrapper).</p><hr><h2 id="visibility-driven-row-sizing" tabindex="-1">Visibility-driven row sizing <a class="header-anchor" href="#visibility-driven-row-sizing" aria-label="Permalink to &quot;Visibility-driven row sizing&quot;">​</a></h2><p>Home Assistant&#39;s <code>hui-card</code> wrapper hides cards by setting <code>display: none</code>. In a standard CSS Grid, a <code>display: none</code> item does not contribute to track sizing, so a row with only hidden cards collapses to <code>0px</code> naturally. In practice, Home Assistant&#39;s layout context does not provide the grid engine with a definite available block-size, so <code>fr</code> tracks expand to the max-content of their items rather than filling the remaining space. This makes <code>minmax(0,auto)</code> tracks collapse correctly but <code>1fr</code> tracks wrong.</p><p>The view solves this entirely in JS:</p><h3 id="baserows-and-visibilityrows" tabindex="-1"><code>_baseRows</code> and <code>_visibilityRows</code> <a class="header-anchor" href="#baserows-and-visibilityrows" aria-label="Permalink to &quot;`_baseRows` and `_visibilityRows`&quot;">​</a></h3><p><code>_baseRows</code> holds the row tracks as parsed from config (never modified at runtime). After every card placement, <code>_collectVisibilityRows()</code> scans the placed cards for a non-empty <code>visibility</code> array, any condition type or shape; conditions are <strong>not</strong> parsed. For each card with a definite <code>layout.height</code> and a <code>grid-area</code> it records <code>{ rowIndex, cardEl, targetHeight }</code> in <code>_visibilityRows</code>.</p><p>The view deliberately never evaluates conditions itself. Home Assistant&#39;s <code>hui-card</code> owns that (since Home Assistant 2026.10 stateful conditions are evaluated by core over a <code>subscribe_condition</code> websocket subscription, and Home Assistant&#39;s Visibility editor rewrites <code>state</code>/<code>numeric_state</code> conditions from lovelace <code>entity</code> shape into core <code>entity_id</code> shape). The view reads the outcome: <code>hui-card</code> toggles its <code>hidden</code> attribute and fires a bubbling, composed <code>card-visibility-changed</code> event, the same signal <code>hui-section</code> uses.</p><h3 id="applyvisibilityrowheights" tabindex="-1"><code>_applyVisibilityRowHeights()</code> <a class="header-anchor" href="#applyvisibilityrowheights" aria-label="Permalink to &quot;`_applyVisibilityRowHeights()`&quot;">​</a></h3><p>Called from: end of <code>_placeCards()</code>, every <code>updated()</code> (after Lit renders), and (rAF-debounced via <code>_scheduleRowHeights()</code>) every <code>card-visibility-changed</code> event and every host resize. It is <strong>not</strong> called from <code>set hass()</code>: entity updates reach it only through hui-card&#39;s visibility event, so ordinary state changes cost no layout reads.</p><ol><li><strong>Build candidate rows</strong>: start from <code>_baseRows</code>; a visibility row gets <code>targetHeight</code> if the view is in edit mode or <strong>any</strong> of its registered cards is not <code>hidden</code>, otherwise <code>&#39;0px&#39;</code>.</li><li><strong>Identify <code>fr</code> tracks</strong>: locate all <code>Nfr</code> tracks in the candidate rows.</li><li><strong>Resolve non-fr sizes</strong>: temporarily write the rows with every <code>fr</code> replaced by <code>0px</code> and force a reflow (<code>getComputedStyle</code>), so the browser evaluates all <code>clamp()</code>, <code>vh</code>, <code>px</code>, and <code>min()</code>/<code>max()</code> tracks to their actual pixel sizes.</li><li><strong>Compute fr allocation</strong>: <code>frSpace = hostHeight - sum(non-fr rows) - sum(gaps)</code>. This is exact regardless of what the CSS Grid engine would have done.</li><li><strong>Final write</strong>: replace every <code>Nfr</code> track with <code>round(frSpace × N / totalFR)px</code> and write <code>grid.style.gridTemplateRows</code> directly (bypassing Lit to avoid a re-render feedback loop).</li></ol><p>Nested <code>hui-card</code>s (inside an MSD control, <code>lcards-layout-card</code> child, or elbow symbiont) never reach the view&#39;s listener: the enclosing top-level <code>hui-card</code> catches and stops <code>card-visibility-changed</code> from its own inner element.</p><h3 id="resizeobserver" tabindex="-1"><code>ResizeObserver</code> <a class="header-anchor" href="#resizeobserver" aria-label="Permalink to &quot;`ResizeObserver`&quot;">​</a></h3><p>A <code>ResizeObserver</code> on the host element (created in <code>connectedCallback</code>, torn down in <code>disconnectedCallback</code>) fires <code>_applyVisibilityRowHeights()</code> via a <code>requestAnimationFrame</code> debounce whenever the host&#39;s bounding box changes: window resize, Home Assistant sidebar toggle, devtools open/close. This keeps row allocations correct across all viewport changes without polling.</p><h3 id="debugging-row-sizing" tabindex="-1">Debugging row sizing <a class="header-anchor" href="#debugging-row-sizing" aria-label="Permalink to &quot;Debugging row sizing&quot;">​</a></h3><p><code>scripts/lcards-layout-debug.js</code> is a console paste script: run it on a dashboard with a layout view (or with the view selected in the DevTools Elements panel) to print each row&#39;s configured track against its computed height, the <code>_baseRows</code> / <code>_visibilityRows</code> state, unexpected <code>0px</code> rows and whether the host <code>ResizeObserver</code> is connected.</p><hr><h2 id="persistence-event-flow" tabindex="-1">Persistence &amp; event flow <a class="header-anchor" href="#persistence-event-flow" aria-label="Permalink to &quot;Persistence &amp; event flow&quot;">​</a></h2><p>Home Assistant hands the view three inputs via setters: <code>hass</code>, <code>lovelace</code>, and <code>cards</code> (pre-built card elements). The view never pushes config to Home Assistant except through one funnel.</p><h3 id="serialized-saves" tabindex="-1">Serialized saves <a class="header-anchor" href="#serialized-saves" aria-label="Permalink to &quot;Serialized saves&quot;">​</a></h3><p><code>_saveViewConfig()</code> coalesces concurrent edits into a single in-flight chain and <strong>always rebases on the latest <code>lovelace.config</code></strong> at the moment each write runs. This prevents the <em>&quot;Dashboard updated in another session&quot;</em> error that stale-snapshot saves caused when several edits (resize commit, area create, card add) fired in quick succession.</p><h3 id="card-add-edit-interception" tabindex="-1">Card add / edit interception <a class="header-anchor" href="#card-add-edit-interception" aria-label="Permalink to &quot;Card add / edit interception&quot;">​</a></h3><p>Home Assistant&#39;s create-card and edit-card dialogs save <strong>directly via <code>lovelace.saveConfig()</code></strong>, bypassing events. The view&#39;s <code>lovelace</code> setter diffs <code>prevCards</code> against the new cards:</p><ul><li><strong>Add</strong> (length grew) with a pending area → injects <code>view_layout.grid-area</code> into the new card, then re-saves.</li><li><strong>Edit</strong> (same length) with a pending edit → restores <code>view_layout</code> if Home Assistant stripped it.</li></ul><h3 id="area-lifecycle-reconciliation" tabindex="-1">Area lifecycle reconciliation <a class="header-anchor" href="#area-lifecycle-reconciliation" aria-label="Permalink to &quot;Area lifecycle reconciliation&quot;">​</a></h3><p>Per-area settings (<code>layout.areas</code>) are keyed by area name, so they must track renames and deletions:</p><ul><li><strong>Rename</strong>: the overlay emits <code>area-renamed {from,to}</code> <em>before</em> <code>grid-state-changed</code>; the view migrates the key (<code>renameAreaSettings</code>) without saving, and the following grid-state save persists it.</li><li><strong>Delete / track removal</strong>: <code>_onGridStateChanged</code> prunes orphans via <code>pruneAreaSettings</code> against the current area names.</li></ul><p>All of these route back through <code>_saveViewConfig</code>.</p><hr><h2 id="the-layout-card" tabindex="-1">The layout card <a class="header-anchor" href="#the-layout-card" aria-label="Permalink to &quot;The layout card&quot;">​</a></h2><p><code>LCARdSLayoutCard</code> (<code>src/cards/lcards-layout-card.js</code>) is a plain <code>LitElement</code> with <code>CARD_TYPE = &#39;layout-card&#39;</code>, a schema, a lazy <code>getConfigElement()</code> and no <code>LCARdSCard</code> features (no rules, templates or entity subscriptions of its own; its children have theirs).</p><ul><li><strong>Children.</strong> Home Assistant gives a <em>view</em> pre-built card elements, but not a card, so the card builds them. <code>setConfig()</code> deep-clones the config, parses the layout (<code>parseLayoutConfig()</code>) and rebuilds the children only when <code>cards</code> changed (a layout-only change re-places the existing ones). <code>_createChild()</code> prefers a <code>hui-card</code> wrapper (native Visibility, lifecycle, <code>preview</code>), falls back to <code>loadCardHelpers().createCardElement()</code>, then to a registered <code>custom:</code> element (outside Home Assistant: docs live demos and the browser test harness), and finally to <code>hui-error-card</code>.</li><li><strong>HASS.</strong> The <code>hass</code> setter passes the object to every child (<code>_propagateHass()</code>).</li><li><strong>Placement.</strong> <code>updated()</code> calls <code>_placeCards()</code> when the config, the grid state or <code>editing</code> changed: it empties <code>#grid-root</code>, appends the area surfaces (<code>renderAreaSurfaces()</code>), and appends every child with <code>applyCardPlacement()</code> and <code>applyGridItemHeight()</code>. The host height mirrors <code>layout.height</code> (default <code>100%</code>), because a percentage host in a content-sized row would collapse to 0.</li><li><strong>Media queries.</strong> <code>layout.mediaquery</code> overrides are matched with <code>matchMedia()</code> listeners (<code>_setupMediaQueries()</code>) and merged into the drawn grid by <code>_activeGrid()</code>; while <code>editing</code> is set (in the studio) the base layout is always drawn, because that is what the studio edits.</li><li><strong>Edit mode.</strong> <code>preview</code> (set by <code>hui-card</code> in dashboard edit mode) is passed to the children, so like <code>hui-stack-card</code> they stay visible when their Visibility conditions are not met. <code>editing</code> (set by the studio) reserves the overlay gutter (<code>buildGridStyle(..., { editMode: &#39;grid&#39; })</code>).</li><li><strong>Not in the card:</strong> the view&#39;s visibility-driven row sizing and its in-place editor. A row of a layout card holding only hidden cards follows plain CSS Grid rules.</li></ul><hr><h2 id="the-layout-studio" tabindex="-1">The Layout Studio <a class="header-anchor" href="#the-layout-studio" aria-label="Permalink to &quot;The Layout Studio&quot;">​</a></h2>',66)),(t(),r(c,null,{default:o(()=>[i(d,{id:"mermaid-411",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20HA%20as%20Home%20Assistant%20card%20editor%0A%20%20%20%20participant%20Ed%20as%20lcards-layout-card-editor%0A%20%20%20%20participant%20St%20as%20lcards-layout-studio-dialog%0A%20%20%20%20participant%20Pv%20as%20preview%20lcards-layout-card%0A%20%20%20%20participant%20Ov%20as%20lcards-grid-edit-overlay%0A%20%20%20%20HA-%3E%3EEd%3A%20setConfig(config)%0A%20%20%20%20Ed-%3E%3ESt%3A%20createElement%2C%20hass%2C%20config%20(deep%20copy)%2C%20mountDialogNearHomeAssistant()%0A%20%20%20%20St-%3E%3EPv%3A%20createElement('lcards-layout-card')%2C%20editing%20%3D%20true%2C%20setConfig(working%20copy)%0A%20%20%20%20St-%3E%3EOv%3A%20createElement('lcards-grid-edit-overlay')%2C%20hideCardMode%2C%20hideSettings%2C%20grid%20state%0A%20%20%20%20Ov-%3E%3ESt%3A%20grid-state-changed%2C%20area-*%2C%20layout-settings-changed%2C%20add-card-to-area%0A%20%20%20%20St-%3E%3ESt%3A%20_commit(new%20working%20config)%0A%20%20%20%20St-%3E%3EPv%3A%20setConfig(working%20copy)%0A%20%20%20%20St-%3E%3EOv%3A%20columns%2C%20rows%2C%20areas%2C%20gap%2C%20cardConfigs%2C%20layout%0A%20%20%20%20Note%20over%20St%3A%20Save%3A%20config-changed%20with%20the%20working%20config.%20Cancel%20or%20close%3A%20config-changed%20with%20the%20initial%20config%0A%20%20%20%20St-%3E%3EEd%3A%20config-changed%0A%20%20%20%20Ed-%3E%3EHA%3A%20config-changed%20(fireEvent)%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[s(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a('<ul><li><strong>Mounting.</strong> The editor creates the dialog on <strong>Open Layout Studio</strong> and mounts it with <code>mountDialogNearHomeAssistant()</code> (inside <code>home-assistant</code>, so Home Assistant&#39;s Lit contexts reach <code>ha-dialog</code> and the pickers). The editor removes it on <code>closed</code> and on its own disconnect.</li><li><strong>Working copy.</strong> The <code>config</code> setter keeps <code>_initialConfig</code> and <code>_workingConfig</code> (both deep copies). Overlay events (<code>grid-state-changed</code>, <code>area-renamed</code>, <code>area-settings-changed</code>, <code>layout-settings-changed</code>, <code>area-cards-changed</code>, <code>add-card-to-area</code>) and the tabs change the working copy through <code>_commit()</code>, which re-renders the studio and pushes the copy to the preview and the overlay (<code>_syncCanvas()</code>). <code>grid-preview-changed</code> (a drag in progress) only writes the preview&#39;s <code>grid-template-*</code> styles.</li><li><strong>Save and Cancel.</strong> Nothing reaches Home Assistant while you edit. <strong>Save</strong> dispatches one <code>config-changed</code> with the working config; <strong>Cancel</strong>, Escape or closing the dialog dispatches <code>config-changed</code> with the initial config, so the card is never left in an intermediate state. <code>_handled</code> makes sure only the first of them fires (the dialog&#39;s asynchronous <code>closed</code> event follows a save).</li><li><strong>Measuring.</strong> A <code>ResizeObserver</code> on the preview&#39;s <code>#grid-root</code> feeds <code>measureGridFrame()</code> (resolved px tracks and the first cell&#39;s offset) to the overlay, so its ghost grid matches content-sized (<code>auto</code>) rows; the overlay is refreshed again one frame and 250 ms after opening, after the dialog animation.</li><li><strong>Tabs.</strong> <em>Layout</em>: grid and per-area settings (the overlay&#39;s own settings panel is hidden with <code>hideSettings</code>). <em>One tab per card</em>: placement (area, alignment, overflow, written to <code>view_layout</code>) and an inline <code>hui-card-element-editor</code>; its changes are committed quietly (<code>_commitQuiet()</code>, the preview updates without re-rendering the studio, so the editor keeps its input state). <em>YAML</em>: <code>lcards-studio-yaml-tab</code> with the layout card schema.</li><li><strong>Adding cards.</strong> The overlay&#39;s per-area <strong>Add card</strong> opens Home Assistant&#39;s <code>hui-card-picker</code> in an <code>ha-dialog</code>. Home Assistant registers the picker only after its own create-card dialog has opened once; when it is missing the studio shows an info dialog instead.</li><li><strong>Removing cards</strong> asks first (<code>showConfirmDeleteDialog()</code>) and can be undone by cancelling the studio.</li></ul><hr><h2 id="drop-in-compatibility" tabindex="-1">Drop-in compatibility <a class="header-anchor" href="#drop-in-compatibility" aria-label="Permalink to &quot;Drop-in compatibility&quot;">​</a></h2><p>The schema mirrors <code>custom:grid-layout</code> (lovelace-layout-card): <code>layout.{grid-template-*, grid-gap, height, margin, padding, card_margin, card_overflow, mediaquery}</code> plus flat <code>cards[]</code> with <code>view_layout</code>. The grid renderer is ~50 lines of CSS plumbing replicated trivially; the value-add is the visual editor. Two intentional differences:</p><ul><li><strong><code>layout.areas</code></strong> (surface decoration) is an LCARdS-only, optional, additive namespace that <code>custom:grid-layout</code> ignores, so configs stay portable in both directions.</li><li><strong><code>view_layout.show</code> is not implemented.</strong> Per-card conditions defer to Home Assistant&#39;s native card Visibility (<code>hui-card</code>); a migrated config using <code>show</code> ignores that key.</li></ul>',5))])}const A=n(g,[["render",p]]);export{b as __pageData,A as default};
